"""Validate actual H014 serial lineage and address-free provisioning, read only."""
import argparse,datetime,hashlib,json,os,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
p=argparse.ArgumentParser();p.add_argument('--source',required=True,type=Path);p.add_argument('--output',required=True,type=Path);a=p.parse_args();source=a.source.resolve();out=a.output.resolve();assert source.is_relative_to(ROOT/'simulation/outputs/H-014') and out.is_relative_to(ROOT/'simulation/outputs/H-014');out.mkdir(parents=True,exist_ok=False);started=datetime.datetime.now(datetime.timezone.utc).isoformat()
r=json.loads((source/'result.json').read_bytes());assert r['success'];raw=source/'native.jsonl';rows=[json.loads(x)for x in raw.read_bytes().splitlines()];tx=[x for x in rows if x.get('direction')=='host_tx'];events=[x for x in rows if x.get('direction')=='device_rx'];configs=[x for x in tx if x['command']['cmd']=='discover_config'];assert len(configs)==2 and {x['node_id']for x in configs}==set(r['labels'].values())
for row in configs:
 c=row['command'];assert set(c)=={'cmd','nonce','group','channel','autostart'} and c['group']==r['group'] and c['channel']==6 and c['autostart'] is True
assert not any(x['command']['cmd']in ('config','deploy','neighbor_probe')for x in tx)
sends=[x for x in tx if x['command']['cmd']=='send'];assert len(sends)==2;proof=[]
for packet,send in zip(r['packets'],sends):
 identity=packet['identity'];assert send['node_id']==r['labels']['A'] and send['command']['dst']==identity['dst'] and send['command']['payload_hex']==packet['payload_hex']
 same=[x for x in events if all(x['event'].get(k)==v for k,v in identity.items())]
 admitted=[x for x in same if x['event'].get('event')=='tx_queued' and x['event']['node_id']==r['labels']['A']];submitted=[x for x in same if x['event'].get('event')=='tx_submit' and x['event']['node_id']==r['labels']['A'] and x['event'].get('next_hop')==r['labels']['B']];rx=[x for x in same if x['event'].get('event')=='rx_local' and x['event']['node_id']==r['labels']['B']];assert len(admitted)==1 and len(submitted)==1 and len(rx)==1 and rx[0]['event']['payload_hex']==send['command']['payload_hex'] and bytes.fromhex(rx[0]['event']['payload_hex'])==packet['text'].encode('utf-8')
 proof.append(dict(identity=identity,host_send_line=send['capture_line'],admission_line=admitted[0]['capture_line'],submit_line=submitted[0]['capture_line'],destination_line=rx[0]['capture_line'],destination_port=rx[0]['port'],payload_bytes=len(bytes.fromhex(packet['payload_hex']))))
lost=next(x for x in r['markers']if x['phase']=='A_observed_B_lost')['neighbor'];assert lost['state']=='lost' and lost['age_ms']>=12000
assert r['B_after_reset_info']['boot_id']!=r['initial_info']['B']['boot_id'];confirmed=[x for x in r['markers']if x['phase']=='pair_bidirectional'];assert confirmed[0]['A_neighbor']['boot_id']==r['initial_info']['B']['boot_id'] and confirmed[1]['A_neighbor']['boot_id']==r['B_after_reset_info']['boot_id'];assert all(r['stop_confirmed'].values()) and r['all_ports_closed']
report=dict(success=True,address_free_radio_provisioning=True,configuration_commands=configs,no_static_table_or_explicit_probe=True,business_sends=len(sends),unique_endpoint_deliveries=len(proof),packet_proof=proof,old_B_boot=r['initial_info']['B']['boot_id'],new_B_boot=r['B_after_reset_info']['boot_id'],initial_A_neighbors_empty=r['A_before_B']==[],native_sha256=hashlib.sha256(raw.read_bytes()).hexdigest(),limitations=['Host serial bindings know local device identities; RF provisioning contains only common group/channel, not peer addresses.','Old-peer-boot replaced in the actual table; late old RF replay was not physically injected.','No Ubuntu physical hotplug or E2 LocalClient physical API verification in this H serial application run.'])
(out/'result.json').write_text(json.dumps(report,indent=2),encoding='utf-8');m=json.loads((ROOT/'coordination/templates/RUN_MANIFEST.json').read_bytes());m.update(template_only=False,task_id='H-014',run_id=out.name,started_at=started,finished_at=datetime.datetime.now(datetime.timezone.utc).isoformat(),worktree=str(ROOT),command=[sys.executable,*sys.argv],python_executable=sys.executable,process_id=os.getpid(),output_directory=str(out),data_and_weights_sha256={str(raw):report['native_sha256']},status='passed',exit_code=0,limitations=report['limitations']);(out/'RUN_MANIFEST.json').write_text(json.dumps(m,indent=2),encoding='utf-8');print(json.dumps({k:report[k]for k in ('success','address_free_radio_provisioning','business_sends','unique_endpoint_deliveries')}))
